/bin/bash -c "python3 - <<'PY'
from itertools import product
vecs=list(product(range(3),repeat=2))
def R(v): return ((-v[1])%3, v[0])
def Rpow(v,p):
    for _ in range(p): v=R(v)
    return v
visited=set(); orbits=[]
for v in vecs:
    if v in visited: continue
    o=[]
    for p in range(4):
        w=Rpow(v,p)
        if w not in o: o.append(w)
    visited.update(o); orbits.append(o)
print('momentum orbits:', orbits)
for o in orbits:
    print(o, 'stabilizer powers', [p for p in range(4) if Rpow(o[0],p)==o[0]])
PY"

